-- Frozen pre-migrations schema, matching EnsureCreated at commit 807ac97.
CREATE EXTENSION IF NOT EXISTS postgis;

CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE "Roles" (
    "Id" uuid NOT NULL,
    "Name" character varying(256),
    "NormalizedName" character varying(256),
    "ConcurrencyStamp" text,
    CONSTRAINT "PK_Roles" PRIMARY KEY ("Id")
);

CREATE TABLE "Users" (
    "Id" uuid NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UserName" character varying(256),
    "NormalizedUserName" character varying(256),
    "Email" character varying(256),
    "NormalizedEmail" character varying(256),
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);

CREATE TABLE "RoleClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" uuid NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_RoleClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RoleClaims_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Investigations" (
    "Id" uuid NOT NULL,
    "Name" text NOT NULL,
    "Description" text,
    "StartsAt" timestamp with time zone,
    "EndsAt" timestamp with time zone,
    "SearchConditions" text,
    "IsPublic" boolean NOT NULL,
    "AccessCodeHash" text,
    "AccessCode" text,
    "AccessCodeVersion" integer NOT NULL,
    "AccessCodeUpdatedAt" timestamp with time zone,
    "OwnerId" uuid,
    "Status" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Investigations" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Investigations_Users_OwnerId" FOREIGN KEY ("OwnerId") REFERENCES "Users" ("Id")
);

CREATE TABLE "UserClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_UserClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_UserClaims_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserLogins" (
    "LoginProvider" text NOT NULL,
    "ProviderKey" text NOT NULL,
    "ProviderDisplayName" text,
    "UserId" uuid NOT NULL,
    CONSTRAINT "PK_UserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_UserLogins_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserRoles" (
    "UserId" uuid NOT NULL,
    "RoleId" uuid NOT NULL,
    CONSTRAINT "PK_UserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_UserRoles_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_UserRoles_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserTokens" (
    "UserId" uuid NOT NULL,
    "LoginProvider" text NOT NULL,
    "Name" text NOT NULL,
    "Value" text,
    CONSTRAINT "PK_UserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_UserTokens_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Findings" (
    "Id" uuid NOT NULL,
    "InvestigationId" uuid NOT NULL,
    "SubmittedBy" text NOT NULL,
    "Name" text,
    "Description" text,
    "ObservedAt" timestamp with time zone NOT NULL,
    "SubmittedAt" timestamp with time zone NOT NULL,
    "ImageContentType" text NOT NULL,
    "ImageFileName" text NOT NULL,
    "ImageData" bytea NOT NULL,
    "Geometry" geometry (Point, 4326) NOT NULL,
    "IsDeleted" boolean NOT NULL,
    "DeletedAt" timestamp with time zone,
    CONSTRAINT "PK_Findings" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Findings_Investigations_InvestigationId" FOREIGN KEY ("InvestigationId") REFERENCES "Investigations" ("Id") ON DELETE CASCADE
);

CREATE TABLE "InvestigationAdmins" (
    "InvestigationId" uuid NOT NULL,
    "AdminId" uuid NOT NULL,
    "IsOwner" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_InvestigationAdmins" PRIMARY KEY ("InvestigationId", "AdminId"),
    CONSTRAINT "FK_InvestigationAdmins_Investigations_InvestigationId" FOREIGN KEY ("InvestigationId") REFERENCES "Investigations" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_InvestigationAdmins_Users_AdminId" FOREIGN KEY ("AdminId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "InvestigationMaps" (
    "Id" uuid NOT NULL,
    "InvestigationId" uuid NOT NULL,
    "Name" text NOT NULL,
    "ContentType" text NOT NULL,
    "Data" bytea NOT NULL,
    "West" double precision NOT NULL,
    "South" double precision NOT NULL,
    "East" double precision NOT NULL,
    "North" double precision NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_InvestigationMaps" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_InvestigationMaps_Investigations_InvestigationId" FOREIGN KEY ("InvestigationId") REFERENCES "Investigations" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ReferencePoints" (
    "Id" uuid NOT NULL,
    "InvestigationId" uuid NOT NULL,
    "Type" text NOT NULL,
    "Label" text NOT NULL,
    "Geometry" geometry (Point, 4326) NOT NULL,
    CONSTRAINT "PK_ReferencePoints" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ReferencePoints_Investigations_InvestigationId" FOREIGN KEY ("InvestigationId") REFERENCES "Investigations" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Tracks" (
    "Id" uuid NOT NULL,
    "InvestigationId" uuid NOT NULL,
    "Callsign" text NOT NULL,
    "SourceFile" text,
    "AssignedGroup" text,
    "SectorId" uuid,
    "Notes" text,
    "StartedAt" timestamp with time zone,
    "EndedAt" timestamp with time zone,
    "Pod" double precision,
    "Geometry" geometry (LineString, 4326) NOT NULL,
    "ImportedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Tracks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Tracks_Investigations_InvestigationId" FOREIGN KEY ("InvestigationId") REFERENCES "Investigations" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UserSessions" (
    "Id" uuid NOT NULL,
    "InvestigationId" uuid NOT NULL,
    "TokenHash" text NOT NULL,
    "Callsign" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "LastSeenAt" timestamp with time zone NOT NULL,
    "RevokedAt" timestamp with time zone,
    "AccessCodeVersion" integer NOT NULL,
    CONSTRAINT "PK_UserSessions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_UserSessions_Investigations_InvestigationId" FOREIGN KEY ("InvestigationId") REFERENCES "Investigations" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Zones" (
    "Id" uuid NOT NULL,
    "InvestigationId" uuid NOT NULL,
    "Name" text NOT NULL,
    "Instructions" text,
    "Status" text NOT NULL,
    "SearchMethod" text NOT NULL,
    "Priority" integer NOT NULL,
    "AssignedGroup" text,
    "Searched" boolean NOT NULL,
    "SearchedAt" timestamp with time zone,
    "Points" integer NOT NULL,
    "ShowName" boolean NOT NULL,
    "ShowArea" boolean NOT NULL,
    "Poa" double precision,
    "IsDeleted" boolean NOT NULL,
    "DeletedAt" timestamp with time zone,
    "Geometry" geometry (Geometry, 4326) NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Zones" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Zones_Investigations_InvestigationId" FOREIGN KEY ("InvestigationId") REFERENCES "Investigations" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_Findings_Geometry" ON "Findings" USING gist ("Geometry");

CREATE INDEX "IX_Findings_InvestigationId" ON "Findings" ("InvestigationId");

CREATE INDEX "IX_InvestigationAdmins_AdminId" ON "InvestigationAdmins" ("AdminId");

CREATE INDEX "IX_InvestigationMaps_InvestigationId" ON "InvestigationMaps" ("InvestigationId");

CREATE INDEX "IX_Investigations_OwnerId" ON "Investigations" ("OwnerId");

CREATE INDEX "IX_ReferencePoints_Geometry" ON "ReferencePoints" USING gist ("Geometry");

CREATE INDEX "IX_ReferencePoints_InvestigationId" ON "ReferencePoints" ("InvestigationId");

CREATE INDEX "IX_RoleClaims_RoleId" ON "RoleClaims" ("RoleId");

CREATE UNIQUE INDEX "RoleNameIndex" ON "Roles" ("NormalizedName");

CREATE INDEX "IX_Tracks_Geometry" ON "Tracks" USING gist ("Geometry");

CREATE INDEX "IX_Tracks_InvestigationId" ON "Tracks" ("InvestigationId");

CREATE INDEX "IX_UserClaims_UserId" ON "UserClaims" ("UserId");

CREATE INDEX "IX_UserLogins_UserId" ON "UserLogins" ("UserId");

CREATE INDEX "IX_UserRoles_RoleId" ON "UserRoles" ("RoleId");

CREATE INDEX "EmailIndex" ON "Users" ("NormalizedEmail");

CREATE UNIQUE INDEX "UserNameIndex" ON "Users" ("NormalizedUserName");

CREATE INDEX "IX_UserSessions_InvestigationId" ON "UserSessions" ("InvestigationId");

CREATE UNIQUE INDEX "IX_UserSessions_TokenHash" ON "UserSessions" ("TokenHash");

CREATE INDEX "IX_Zones_Geometry" ON "Zones" USING gist ("Geometry");

CREATE INDEX "IX_Zones_InvestigationId" ON "Zones" ("InvestigationId");
